<?php $admin_title='Stock Adjustments';include '_header.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_ok($_POST['csrf']??''))$msg='Security token expired.';else{try{$pid=(int)($_POST['product_id']??0);$qty=(int)($_POST['quantity']??0);$direction=$_POST['direction']??'';$reason=trim($_POST['reason']??'');if(!$pid||$qty<1||!in_array($direction,['add','remove'])||$reason==='')throw new Exception('Complete all fields and provide a reason.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT quantity FROM products WHERE id=? FOR UPDATE');$q->execute([$pid]);$before=$q->fetchColumn();if($before===false)throw new Exception('Product not found.');$before=(int)$before;$after=$direction==='add'?$before+$qty:$before-$qty;if($after<0)throw new Exception('Adjustment cannot make stock negative.');$pdo->prepare('UPDATE products SET quantity=? WHERE id=?')->execute([$after,$pid]);$pdo->prepare('INSERT INTO stock_transactions(product_id,type,quantity,stock_before,stock_after,reason,reference_no,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$pid,$direction==='add'?'IN':'OUT',$qty,$before,$after,'Adjustment: '.$reason,trim($_POST['reference_no']??''),admin_user()['id']??null]);$pdo->commit();$msg='Stock adjustment saved. New quantity: '.$after;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$msg=$e->getMessage();}}}$products=$pdo->query("SELECT id,name,sku,quantity,unit FROM products WHERE status='active' ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT * FROM v_stock_history WHERE reason LIKE 'Adjustment:%' ORDER BY created_at DESC LIMIT 100")->fetchAll();?><?php if($msg):?><div class="panel"><b><?=e($msg)?></b></div><?php endif;?><div class="panel"><div class="panel-head"><h2>Correct Physical Stock Count</h2></div><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><div class="form-grid"><div class="form-group"><label>Product *</label><select class="form-control" name="product_id" required><option value="">Choose product</option><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?> — recorded: <?=$x['quantity']?> <?=e($x['unit'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Adjustment direction</label><select class="form-control" name="direction"><option value="add">Increase recorded stock</option><option value="remove">Decrease recorded stock</option></select></div><div class="form-group"><label>Quantity difference *</label><input class="form-control" type="number" name="quantity" min="1" required></div><div class="form-group"><label>Reference</label><input class="form-control" name="reference_no"></div><div class="form-group full"><label>Reason *</label><input class="form-control" name="reason" required placeholder="Physical count difference, damaged goods, approved correction"></div></div><p><button class="btn btn-primary">Save Adjustment</button></p></form><small class="muted">Adjustments are recorded in stock history; they do not erase previous transactions.</small></div><div class="panel"><div class="panel-head"><h2>Recent Adjustments</h2></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Change</th><th>Before</th><th>After</th><th>Reason</th><th>Reference</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['product_name'])?></td><td><?=$r['type']==='IN'?'+':'-'?><?=$r['quantity']?></td><td><?=$r['stock_before']?></td><td><?=$r['stock_after']?></td><td><?=e($r['reason'])?></td><td><?=e($r['reference_no'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No adjustments yet.</td></tr><?php endif;?></tbody></table></div></div><?php include '_footer.php';?>